const listarBuzones = `-- name: ListarBuzones :many
SELECT id, empresa_id, nombre, correo, imap_host, imap_puerto, imap_tls, imap_usuario, imap_contrasena, imap_carpeta, imap_carpeta_procesados, smtp_host, smtp_puerto, smtp_tls, smtp_usuario, smtp_contrasena, categoria_id, prioridad, activo, uid_validity, ultimo_uid, ultima_lectura_en, ultimo_error, version, created_at, updated_at, authserv_id FROM soporte.buzones
WHERE id > $1
  AND (($2::bigint IS NULL AND empresa_id IS NULL) OR empresa_id = $2)
ORDER BY id
LIMIT $3
`

type ListarBuzonesParams struct {
	DespuesDe int64
	EmpresaID *int64
	Limite    int32
}

func (q *Queries) ListarBuzones(ctx context.Context, arg ListarBuzonesParams) ([]SoporteBuzon, error) {
	rows, err := q.db.Query(ctx, listarBuzones, arg.DespuesDe, arg.EmpresaID, arg.Limite)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SoporteBuzon
	for rows.Next() {
		var i SoporteBuzon
		if err := rows.Scan(
			&i.ID,
			&i.EmpresaID,
			&i.Nombre,
			&i.Correo,
			&i.ImapHost,
			&i.ImapPuerto,
			&i.ImapTls,
			&i.ImapUsuario,
			&i.ImapContrasena,
			&i.ImapCarpeta,
			&i.ImapCarpetaProcesados,
			&i.SmtpHost,
			&i.SmtpPuerto,
			&i.SmtpTls,
			&i.SmtpUsuario,
			&i.SmtpContrasena,
			&i.CategoriaID,
			&i.Prioridad,
			&i.Activo,
			&i.UidValidity,
			&i.UltimoUid,
			&i.UltimaLecturaEn,
			&i.UltimoError,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.AuthservID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

